#pragma once

// Returns the 'App Version' from IDF. This is generated by the following git command:
// `git describe --always --tags --dirty`
// This string contains:
// - The most recent release tag
// - The number of commits since that tag (if > 0)
// - The git hash (if not on the release tag)
// - `dirt` to indicate that there are uncommitted changes
// And it will truncate at 32 chars (including the null terminator).
// For example:
// release/v0.7.0
// release/v0.7.0-9-g47f5868d
// release/v0.7.0-9-g4fd1a5c9-dirt
// release/v0.7.0-10-g496e01e2-dir
auto GitVersionString() -> const char *;

// The semantic version string, parsed out of the GitVersion
// For example:
// 0.7.0
// 0.6.9999
auto SemanticVersionString() -> const char *;
